package com.miniforce.controller;
import com.miniforce.dto.ContestDtos.*; import com.miniforce.model.User; import com.miniforce.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/contests") public class ContestController {private final ContestService contests;private final CurrentUser current;public ContestController(ContestService c,CurrentUser u){contests=c;current=u;}@GetMapping List<ContestResponse> all(){return contests.all();}@GetMapping("/{id}") ContestResponse get(@PathVariable Long id){return contests.get(id);}@GetMapping("/{id}/problems") List<ContestProblemResponse> problems(@PathVariable Long id){User u=null;try{u=current.require();}catch(Exception ignored){}return contests.problems(id,u);}@PostMapping("/{id}/join") ContestResponse join(@PathVariable Long id){return contests.join(id,current.require());}@GetMapping("/{id}/leaderboard") List<ContestLeaderboardEntry> leaderboard(@PathVariable Long id){return contests.leaderboard(id);}@PostMapping ResponseEntity<ContestResponse> create(@Valid @RequestBody ContestRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(contests.create(r));}@PutMapping("/{id}") ContestResponse update(@PathVariable Long id,@Valid @RequestBody ContestRequest r){return contests.update(id,r);}@DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable Long id){contests.delete(id);return ResponseEntity.noContent().build();}}
